-- Bootstrap only the user-provided organization facts and introductory copy.
-- No beneficiary, donor, financial, attendance or impact statistics are seeded.
begin;
do $$declare item jsonb;rid uuid;begin
 for item in select * from jsonb_array_elements('[{"id":"home","kind":"page","slug":"home","title":"Hope begins with believing.","summary":"In every child. In every family. In the possibility of a brighter tomorrow.","body":"Founded in October 2025, Aminia Hope Foundation is a community-based organization in Entebbe. We work alongside children, families and communities to break the cycle of poverty through practical action.","details":{}},{"id":"about","kind":"page","slug":"about","title":"Believing in people. Building hope.","summary":"Community-led hope, rooted in Entebbe.","body":"Aminia Hope Foundation is a community-based organization founded in October 2025 and based in Entebbe, Wakiso District, Uganda. We work in Katabi and Busabaga to empower communities and our country.\n\n“Aminia” is a Swahili verb meaning to believe, to trust and to have confidence. It is the idea behind everything we do: when people believe in children, families and communities, poverty can be overcome.\n\nWe are committed to integrity, accountability and open reporting to the communities and partners we serve.","details":{"vision":"To break the cycle of poverty and transform lives through hope: hope for every family, a brighter future for every child, and restored hope and dignity for the elderly and the vulnerable.","mission":"To achieve our vision through practical, community-based programmes that support children, families and communities."}},{"id":"education","kind":"programme","slug":"education","title":"Education & child development","summary":"Opening doors to learning and a brighter future for every child.","body":"Opening doors to learning and a brighter future for every child.","details":{}},{"id":"protection","kind":"programme","slug":"protection","title":"Child protection & well-being","summary":"Supporting the safety, dignity and well-being of children.","body":"Supporting the safety, dignity and well-being of children.","details":{}},{"id":"families","kind":"programme","slug":"families","title":"Family support","summary":"Strengthening the families at the heart of our communities.","body":"Strengthening the families at the heart of our communities.","details":{}},{"id":"community","kind":"programme","slug":"community","title":"Community development","summary":"Listening, learning and working together for lasting change.","body":"Listening, learning and working together for lasting change.","details":{}},{"id":"health","kind":"programme","slug":"health","title":"Health, hygiene & basic needs","summary":"Supporting healthier lives and access to everyday essentials.","body":"Supporting healthier lives and access to everyday essentials.","details":{}},{"id":"skills","kind":"programme","slug":"skills","title":"Empowerment & skills","summary":"Building skills, confidence and opportunities for economic empowerment.","body":"Building skills, confidence and opportunities for economic empowerment.","details":{}},{"id":"partnerships","kind":"programme","slug":"partnerships","title":"Partnership & fundraising","summary":"Bringing people and resources together to support community-based work.","body":"Bringing people and resources together to support community-based work.","details":{}},{"id":"accountability","kind":"programme","slug":"accountability","title":"Monitoring & accountability","summary":"Learning from our work and reporting openly to communities and partners.","body":"Learning from our work and reporting openly to communities and partners.","details":{}},{"id":"aminia-kids","kind":"programme","slug":"aminia-kids","title":"Aminia Kids","summary":"Dance, theatre and singing. Nurturing creativity, confidence and hope.","body":"Dance, theatre and singing. Nurturing creativity, confidence and hope.","details":{}},{"id":"community-story","kind":"story","slug":"listening-learning-working-together","title":"Listening, learning, working together","summary":"Hope grows through relationships, shared ideas and community collaboration.","body":"Our approach begins with listening. Aminia Hope Foundation brings people together around practical, community-based programmes for children, families and communities.\n\nWe believe in working alongside the people and partners who share our commitment to dignity and opportunity.","details":{"image":"/images/team-collaboration.jpeg","caption":"Team collaboration — photograph supplied by Aminia Hope Foundation."}}]'::jsonb) loop
  rid:=null;
  insert into content_items(kind,slug,title,summary,body,details,status) values(item->>'kind',item->>'slug',item->>'title',item->>'summary',item->>'body',item->'details','Published') on conflict(kind,slug) do nothing returning id into rid;
  if rid is not null then insert into publications(content_id,version,snapshot) values(rid,1,item-'id');end if;
 end loop;
end $$;
commit;
